import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const o="/assets/add-asset-start.BWVcxz8y.png",i="/assets/add-asset.D6xwZME_.png",f=JSON.parse('{"title":"Adding and Editing Assets","description":"","frontmatter":{},"headers":[],"relativePath":"curating.md","filePath":"curating.md"}'),l={name:"curating.md"};function r(d,e,h,g,p,c){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="adding-and-editing-assets" tabindex="-1">Adding and Editing Assets <a class="header-anchor" href="#adding-and-editing-assets" aria-label="Permalink to &quot;Adding and Editing Assets&quot;">​</a></h1><h2 id="adding-assets" tabindex="-1">Adding Assets <a class="header-anchor" href="#adding-assets" aria-label="Permalink to &quot;Adding Assets&quot;">​</a></h2><p>Once you’ve created at least one template, you can begin adding assets.</p><p>Open the main menu and choose <strong>Manage Assets</strong> › <strong>Add Asset</strong>. Choose the <strong>Template</strong> you’ll be using and the <strong>Collection</strong> the asset belongs to, then click <strong>Continue</strong>. You’ll then be presented with the asset editor for that template.</p><p><img src="'+o+'" alt="The Add Asset page, with Template and Collection chosen and a Continue button"></p><p>To edit an existing asset, open it and click the pencil icon (<strong>Edit Asset</strong>).</p><p><img src="'+i+'" alt="The asset editor, with the template&#39;s fields on the left and the asset settings and Contents list in the right-hand sidebar"></p><h3 id="asset-settings" tabindex="-1">Asset Settings <a class="header-anchor" href="#asset-settings" aria-label="Permalink to &quot;Asset Settings&quot;">​</a></h3><p>The right-hand sidebar holds a handful of settings about the asset, along with its <strong>Asset ID</strong> once it has been saved.</p><h4 id="collection" tabindex="-1">Collection <a class="header-anchor" href="#collection" aria-label="Permalink to &quot;Collection&quot;">​</a></h4><p>The collection not only defines how the asset will be grouped, but also defines where it will be stored in the cloud. You choose it before the editor opens. Changing it later in the sidebar asks you to confirm, then saves the asset and moves it to the new collection. The asset is unavailable while it moves.</p><h4 id="template" tabindex="-1">Template <a class="header-anchor" href="#template" aria-label="Permalink to &quot;Template&quot;">​</a></h4><p>The <strong>Template</strong> menu changes which template the asset uses. Elevator first warns that switching templates may lose data and lists the fields that will be dropped, then saves the asset. If you can edit templates, the <strong>View</strong> link next to the menu opens the template in the template editor.</p><h4 id="status-available-after" tabindex="-1">Status / Available After <a class="header-anchor" href="#status-available-after" aria-label="Permalink to &quot;Status / Available After&quot;">​</a></h4><p>If <strong>Status</strong> is <strong>Not Ready</strong>, or <strong>Available After</strong> is set to a date in the future, the asset will be hidden and not available within the search results. <strong>Available After</strong> will automatically make the asset available in the future. New assets start as <strong>Ready</strong>.</p><h3 id="populating-fields" tabindex="-1">Populating Fields <a class="header-anchor" href="#populating-fields" aria-label="Permalink to &quot;Populating Fields&quot;">​</a></h3><p>All of the fields from your template appear in the main column, each in its own section that you can expand or collapse. The button above the fields (<strong>Expand All</strong> or <strong>Collapse All</strong>) opens or closes every section at once.</p><p>The <strong>Contents</strong> list in the sidebar shows every field. Click a field&#39;s name to jump to it. A check mark appears next to each field you&#39;ve filled in, and a warning icon marks a required field that&#39;s still empty.</p><p>If a field allows multiple entries, click the button below the field, labeled with the field&#39;s name and a plus sign, to add another entry.</p><h3 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h3><p>Click <strong>Save</strong> at the top of the sidebar to save. When you have unsaved changes, <strong>Save</strong> changes from an outlined button to a filled one. The text below it says &quot;No unsaved changes&quot; once everything is saved, and lists any <strong>Missing required</strong> or <strong>Invalid</strong> fields. An asset marked <strong>Ready</strong> can&#39;t be saved while fields are listed there. An asset marked <strong>Not Ready</strong> can be saved at any time.</p><h3 id="uploading-files" tabindex="-1">Uploading Files <a class="header-anchor" href="#uploading-files" aria-label="Permalink to &quot;Uploading Files&quot;">​</a></h3><p>To attach files, drag them onto an <strong>Upload</strong> field, or click <strong>browse files</strong>. If the field accepts only one file, it says &quot;1 file maximum&quot;, and the drop area disappears once a file is attached. To accept more than one, turn on <strong>Allow multiple</strong> for that field in the template. See <a href="/templates.html#field-options">Field Options</a>.</p><p>After starting a file upload, you may keep working on other fields, and the upload will continue. You will be prompted before leaving the page if the upload is incomplete or you have unsaved changes.</p><p>If an upload fails for some reason, save your other changes, refresh the asset, and select the file again.</p><p>After a file is uploaded, a small preview will be displayed. You may add <strong>Alt Text</strong> for the file if you’d like. If <strong>Show Description below Thumbnails</strong> is turned on in <strong>Instance Settings</strong>, the field is labeled <strong>Description / Alt Text</strong> and the text also appears below the file&#39;s thumbnail.</p>',26)])])}const m=t(l,[["render",r]]);export{f as __pageData,m as default};
